INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2f153bd3-cc4d-553e-96e3-2c53b6bc9f90', '74d5312d-6ab3-5ac2-9333-c04914718134', 'text', 'Vocabulary', '{"text": "## Describing People (Adjectives)\n\n**Tall** — Having great height.\n_He is very tall._\n\n**Short** — Not tall.\n_She is not short._\n\n**Young** — Not old.\n_The student is young._\n\n**Kind** — Nice to others.\n_My classmate is kind._\n\n**Smart** — Intelligent.\n_You are very smart._\n\n**Busy** — Working hard.\n_The teacher is busy._\n\n**Funny** — Making people laugh.\n_The story is very funny._\n\n**Calm** — Not worried.\n_I am calm in class._\n\n**Strong** — Having power.\n_He is a strong person._\n\n**Brave** — Not afraid.\n_She is brave today._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
