VALUES ('ded4c185-d7be-57a3-8438-0015bcad75d5', '640f4eb1-e74d-5b61-99a7-3564bb900396', 'text', 'Vocabulary', '{"text": "## Present Simple (Daily Habits)\n\n**Wake** — Stop sleeping.\n_I wake up at seven._\n\n**Eat** — Having food.\n_I eat breakfast every day._\n\n**Drink** — Having liquid.\n_I drink tea in the morning._\n\n**Study** — Learning work.\n_I study English at noon._\n\n**Work** — Doing your job.\n_I work in a school._\n\n**Walk** — Moving by feet.\n_I walk to the library._\n\n**Read** — Looking at books.\n_I read a book at night._\n\n**Talk** — Using words.\n_I talk to my friends._\n\n**Like** — Enjoying something.\n_I like my new class._\n\n**Sleep** — Resting at night.\n_I sleep at ten o''clock._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
