INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c465919c-c1d1-596c-be16-d5c521379d52', '5eb4822d-5ad2-5b39-a833-d621e249aa50', 'text', 'Vocabulary', '{"text": "## ''To Be'' in Questions\n\n**Am I?** — Asking about yourself.\n_Am I in the right class?_\n\n**Is he?** — Asking about a male.\n_Is he a new student?_\n\n**Is she?** — Asking about a female.\n_Is she your friend?_\n\n**Are you?** — Asking the listener.\n_Are you ready to start?_\n\n**Are we?** — Asking the group.\n_Are we in the correct room?_\n\n**Who** — Asking for a person.\n_Who is the teacher?_\n\n**Where** — Asking for location.\n_Where are you from?_\n\n**What** — Asking for things.\n_What is your name?_\n\n**How** — Asking for quality.\n_How are you today?_\n\n**Why** — Asking for reasons.\n_Why are you late?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
