INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('1ca06e2b-ac9a-5520-8f62-382369be932f', '13408548-c919-5bad-8212-cc781d74432f', 'text', 'Vocabulary', '{"text": "## Expressing Ownership (Possession)\n\n**My** — Belonging to me.\n_This is my book._\n\n**Your** — Belonging to you.\n_Is this your pen?_\n\n**His** — Belonging to him.\n_That is his bag._\n\n**Her** — Belonging to her.\n_This is her notebook._\n\n**Our** — Belonging to us.\n_This is our classroom._\n\n**Their** — Belonging to them.\n_Those are their desks._\n\n**Whose** — Asking for ownership.\n_Whose pencil is this?_\n\n**Mine** — It belongs to me.\n_The book is mine._\n\n**Yours** — It belongs to you.\n_Is the bag yours?_\n\n**Name** — Identifying owner.\n_My name is English._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
