INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c116c5e8-f483-5385-b17d-9c06e09fab8f', '39ed052e-e944-545b-b292-f028828d7be6', 'text', 'Vocabulary', '{"text": "## Action Verbs (Present Continuous)\n\n**Am sitting** — Currently resting.\n_I am sitting here now._\n\n**Is writing** — Currently using a pen.\n_She is writing a note._\n\n**Are talking** — Currently speaking.\n_We are talking about English._\n\n**Is reading** — Currently looking at text.\n_He is reading a story._\n\n**Am looking** — Currently seeing.\n_I am looking at you._\n\n**Are listening** — Currently hearing.\n_They are listening well._\n\n**Is studying** — Currently learning.\n_Salma is studying now._\n\n**Am working** — Currently on a task.\n_I am working today._\n\n**Is eating** — Currently having food.\n_He is eating lunch._\n\n**Are walking** — Currently moving.\n_They are walking home._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
