INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b8371da6-7bcd-59dd-9a0a-717f33fff300', 'a8c516a3-38d3-5ed7-847f-bf5e1603c685', 'text', 'Vocabulary', '{"text": "## Using ''Can'' (Ability)\n\n**Can** — Having the ability.\n_I can speak English._\n\n**Cannot** — No ability.\n_I cannot speak fast._\n\n**Help** — Assist.\n_Can you help me?_\n\n**Understand** — Get the meaning.\n_I can understand you._\n\n**Repeat** — Say again.\n_Can you repeat that?_\n\n**Explain** — Make clear.\n_Can you explain this?_\n\n**See** — View.\n_I can see the board._\n\n**Hear** — Sound.\n_I can hear you well._\n\n**Write** — Use pen.\n_Can you write it down?_\n\n**Read** — See words.\n_I can read this word._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
