INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c86ee211-a024-5301-bb68-d2ceeede3aa5', '5f3afe8f-ad59-5ce3-ba78-7bd038df169e', 'text', 'Vocabulary', '{"text": "## Location and Prepositions\n\n**In** — Inside a place.\n_I am in the room._\n\n**On** — Touching the surface.\n_The book is on the desk._\n\n**At** — Specific spot.\n_I am at the door._\n\n**Under** — Below something.\n_The bag is under the chair._\n\n**Next to** — Beside someone.\n_Sit next to your friend._\n\n**Here** — In this place.\n_Come here, please._\n\n**There** — That place.\n_The library is over there._\n\n**Where** — Asking location.\n_Where is the teacher?_\n\n**Inside** — Within.\n_Stay inside the classroom._\n\n**Near** — Not far.\n_The school is near home._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
