INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c82502db-9898-5af3-b1cc-93019e96ce0f', 'c2ff03a5-e246-5855-a30a-12f61a2383c9', 'text', 'Vocabulary', '{"text": "## Polite Requests (Speaking)\n\n**Please** — Showing manners.\n_Please, can you help?_\n\n**Thank you** — Gratitude.\n_Thank you for the help._\n\n**Excuse me** — Getting attention.\n_Excuse me, teacher?_\n\n**Sorry** — Apology.\n_Sorry, I am late._\n\n**Would** — Polite wish.\n_Would you help me?_\n\n**Could** — Polite ability.\n_Could you speak slower?_\n\n**May** — Polite permission.\n_May I come in?_\n\n**Welcome** — Polite response.\n_You are very welcome._\n\n**Help** — Assist.\n_I would like some help._\n\n**Please** — Softening a request.\n_Read this page, please._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
