INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f17a9f34-d438-51a2-beba-08deb5cfcd49', '8943c175-1cb8-53f1-9cdf-c3261c81e217', 'text', 'Vocabulary', '{"text": "## Feelings and States\n\n**Tired** — Need rest.\n_I am very tired today._\n\n**Hungry** — Want food.\n_I am a little hungry._\n\n**Thirsty** — Want drink.\n_I am very thirsty._\n\n**Happy** — Feel joy.\n_I feel happy now._\n\n**Sad** — Not happy.\n_Do not be sad._\n\n**Angry** — Feel mad.\n_I am not angry._\n\n**Worried** — Feel concerned.\n_Are you worried?_\n\n**Excited** — Very happy expectation.\n_I am excited to study._\n\n**Bored** — No interest.\n_I am not bored._\n\n**Well** — Healthy.\n_I am very well._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
