INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('26f4f23b-617c-5b13-b299-14fef1b56ee7', 'a318ff6c-aafa-59db-bffd-8542a3983e2a', 'text', 'Vocabulary', '{"text": "## Asking About Preferences\n\n**Like** — To enjoy something.\n_Do you like tea?_\n\n**Love** — To enjoy something very much.\n_I love learning English._\n\n**Hate** — To strongly dislike.\n_I hate being late._\n\n**Prefer** — Choosing one over another.\n_I prefer coffee to tea._\n\n**Enjoy** — Having a good time.\n_Do you enjoy school?_\n\n**Want** — To have a desire.\n_I want to study now._\n\n**Need** — Something necessary.\n_I need a new book._\n\n**Favorite** — The one you like most.\n_What is your favorite color?_\n\n**Taste** — Describing food flavor.\n_The food tastes good._\n\n**Choose** — Selecting an option.\n_Please choose a topic._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
