INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('7e2eb499-2912-5f96-ab13-5c2e7bc00c23', 'b7fa0bd3-5744-5de2-b0a8-03d44c7dd77e', 'text', 'Vocabulary', '{"text": "## Describing Your Day\n\n**Usually** — Something done often.\n_I usually wake up early._\n\n**Always** — Every time.\n_I always study at night._\n\n**Sometimes** — Now and then.\n_Sometimes I walk to school._\n\n**Never** — Not at any time.\n_I never sleep in class._\n\n**First** — The start of a process.\n_First, I drink water._\n\n**Then** — After that.\n_Then, I go to work._\n\n**After** — Following an event.\n_After school, I rest._\n\n**Before** — Earlier than.\n_Before bed, I read._\n\n**Daily** — Happening every day.\n_This is my daily plan._\n\n**Routine** — A regular way of acting.\n_I have a good routine._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
