INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('54c29e7c-639d-582b-bf8d-cbcccbe66194', '1070f911-4b43-56c9-b1a4-15c0124754bc', 'text', 'Vocabulary', '{"text": "## Making Simple Requests\n\n**Please** — Adding politeness.\n_Can you help, please?_\n\n**Could** — Polite request.\n_Could you pass the pen?_\n\n**Would** — Suggesting a favor.\n_Would you help me today?_\n\n**Mind** — Being bothered by something.\n_Do you mind waiting?_\n\n**Sure** — Agreement to a request.\n_Sure, I can help._\n\n**Problem** — An issue.\n_No problem at all!_\n\n**Hand** — To give something.\n_Hand me the dictionary._\n\n**Bring** — To take to a place.\n_Bring your notes tomorrow._\n\n**Borrow** — Use something and return.\n_Can I borrow your book?_\n\n**Give** — Transferring an item.\n_Give the paper to him._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
