INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d2d6add2-83e1-57c8-81c7-443dc988a5b0', 'e5563be3-42f4-5505-8766-eecafe8c1804', 'text', 'Vocabulary', '{"text": "## Describing Objects\n\n**Big** — Large in size.\n_That is a big desk._\n\n**Small** — Not large.\n_I need a small box._\n\n**New** — Not old.\n_Is your laptop new?_\n\n**Old** — Not new.\n_My pen is very old._\n\n**Color** — Visual characteristic.\n_What color is it?_\n\n**Red** — The color of fire.\n_The marker is red._\n\n**Blue** — The color of sky.\n_I like my blue folder._\n\n**Heavy** — Weighing a lot.\n_The book is too heavy._\n\n**Light** — Easy to carry.\n_My tablet is light._\n\n**Good** — Quality.\n_This is a good computer._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
