INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('6eba2ddd-17a0-5373-bf70-fb2b3a84b7f7', '65cf27a2-74e3-50af-b3f1-59429d8cfe51', 'text', 'Vocabulary', '{"text": "## Expressing Frequency\n\n**Often** — Many times.\n_We often meet here._\n\n**Seldom** — Very rarely.\n_I seldom go there._\n\n**Once** — One time.\n_I study once a day._\n\n**Twice** — Two times.\n_I eat twice a day._\n\n**Every** — All the time.\n_I study every morning._\n\n**Week** — Seven days.\n_Once a week is enough._\n\n**Month** — Four weeks.\n_I go once a month._\n\n**Time** — Measured duration.\n_How many times, please?_\n\n**Again** — Repeating an action.\n_Do it again, please._\n\n**Daily** — Occurring every day.\n_It is a daily habit._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
