INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('55612c59-31f3-56c9-b7b2-d0508fcc7032', 'af28d49e-c9d7-59e1-ba8d-8a1aa81c546f', 'text', 'Vocabulary', '{"text": "## Describing Feelings (Extended)\n\n**Glad** — Pleased.\n_I am glad to see you._\n\n**Nervous** — Slightly anxious.\n_Don''t be nervous now._\n\n**Surprised** — Unexpecting event.\n_I am surprised today!_\n\n**Tired** — Lacking energy.\n_Are you feeling tired?_\n\n**Curious** — Wanting to know.\n_I am curious about that._\n\n**Calm** — Serene state.\n_Try to stay calm._\n\n**Confused** — Not understanding.\n_I am a bit confused._\n\n**Ready** — Prepared.\n_I am ready to speak._\n\n**Hopeful** — Optimistic.\n_I am hopeful for success._\n\n**Proud** — Satisfied with self.\n_I am proud of you._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
