INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2c5b775a-e0e5-5140-8a53-12b384867ad3', '6fddb325-862f-56ab-bbe8-5b0615ee8520', 'text', 'Vocabulary', '{"text": "## Agreeing and Disagreeing\n\n**Agree** — To share an opinion.\n_I agree with you._\n\n**Correct** — Being right.\n_That is correct!_\n\n**True** — A fact.\n_It is true, I know._\n\n**No** — Disagreement.\n_No, I do not agree._\n\n**Wrong** — Incorrect.\n_That answer is wrong._\n\n**Maybe** — Possible.\n_Maybe, let me check._\n\n**Right** — Precise.\n_You are right, teacher._\n\n**Opinion** — A personal thought.\n_What is your opinion?_\n\n**Sure** — Certainty.\n_I am sure about it._\n\n**Okay** — Acceptance.\n_Okay, let us proceed._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
