VALUES ('64aec808-77aa-51cb-8d05-c54ba5702348', '01923a70-223f-5633-bc7c-beb16105f84b', 'text', 'Vocabulary', '{"text": "## Giving Instructions\n\n**Start** — Begin.\n_Start the lesson now._\n\n**Stop** — End action.\n_Stop talking, please._\n\n**Listen** — Attend to sound.\n_Listen to the audio._\n\n**Read** — View text.\n_Read the first sentence._\n\n**Write** — Record text.\n_Write your name here._\n\n**Open** — Uncover.\n_Open your book today._\n\n**Close** — Cover.\n_Close the door, please._\n\n**Sit** — Rest on chair.\n_Sit down, please._\n\n**Stand** — Upright position.\n_Stand up for a moment._\n\n**Follow** — Go after.\n_Follow my instructions._\n"}', 0, NOW(), NOW())
