INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('af651c2f-30af-58fd-bd40-227a4f7e1308', 'd608afd7-af78-5e9f-b622-1adaada0791b', 'text', 'Vocabulary', '{"text": "## Asking About Time/Schedule\n\n**When** — Asking time.\n_When is the class?_\n\n**Time** — Clock reading.\n_What time is it?_\n\n**Early** — Before time.\n_I am early today._\n\n**Late** — After time.\n_I am sorry I am late._\n\n**Today** — Current day.\n_Is today Monday?_\n\n**Soon** — Near time.\n_See you soon!_\n\n**Now** — At this moment.\n_Study with me now._\n\n**Wait** — Stay for time.\n_Please wait for me._\n\n**Hour** — Sixty minutes.\n_I study one hour._\n\n**Clock** — Time tool.\n_Look at the clock._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
