INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('1404df94-eac6-5684-b7a2-044555b47bf0', '3edfb269-5c28-57ea-9642-a9864dcfc2c0', 'text', 'Vocabulary', '{"text": "## Closing Conversations\n\n**Goodbye** — Final parting.\n_Goodbye, have a good day._\n\n**Later** — In the future.\n_See you later!_\n\n**Tomorrow** — Next day.\n_See you tomorrow morning._\n\n**Thanks** — Final gratitude.\n_Thanks for everything._\n\n**Welcome** — Polite response.\n_You are welcome!_\n\n**Nice** — Pleasant comment.\n_It was nice talking._\n\n**Chat** — Informal talk.\n_Let us chat again._\n\n**Take** — Carry/do.\n_Take care of yourself._\n\n**Well** — Healthy state.\n_Stay well, teacher._\n\n**Finish** — Complete.\n_We finish our talk._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
