INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d365a8e0-0af8-53f9-ae17-c45f9ea31441', 'c787c827-f213-5fad-880b-56e5454cc01d', 'text', 'Vocabulary', '{"text": "## Describing Past Activities (Introduction)\n\n**Did** — Used to ask about the past.\n_Did you study yesterday?_\n\n**Was** — Past of\n_is\". \"The class was very good._\n\n**Were** — Past of\n_are\". \"They were in the library._\n\n**Yesterday** — The day before today.\n_I studied English yesterday._\n\n**Before** — Prior to now.\n_I did this before._\n\n**Last** — The most recent time.\n_I went last week._\n\n**Ago** — Time in the past.\n_I learned that an hour ago._\n\n**Finished** — Completed in the past.\n_I finished my work._\n\n**Stayed** — Remained in a place.\n_I stayed at home._\n\n**Worked** — Completed effort.\n_I worked very hard._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
