INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('0c1fd3c5-4dd7-5fed-8c6b-16e312130310', '271fbe0a-c31d-5fd6-bf7d-0efb023c1b83', 'text', 'Vocabulary', '{"text": "## Asking for Information (WH-Questions)\n\n**Who** — Asking about a person.\n_Who is your teacher?_\n\n**What** — Asking about an object/action.\n_What is in your bag?_\n\n**Where** — Asking about a place.\n_Where is the library?_\n\n**When** — Asking about time.\n_When does the class start?_\n\n**Why** — Asking for a reason.\n_Why are you here?_\n\n**How** — Asking about way or degree.\n_How do you spell this?_\n\n**Which** — Choosing between options.\n_Which book is yours?_\n\n**Whose** — Asking about ownership.\n_Whose pen is this?_\n\n**Whom** — Formal object of a person.\n_Whom did you ask?_\n\n**Explain** — Asking for clarification.\n_Can you explain why?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
