INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('9e5168c5-6ec4-52a0-ae16-d2b998999280', '47ca4699-0b87-5b5d-a3ce-4983af630d0f', 'text', 'Vocabulary', '{"text": "## Giving Directions\n\n**Go** — Moving in a direction.\n_Go straight to the door._\n\n**Turn** — Changing your direction.\n_Turn left at the desk._\n\n**Left** — Direction to the west side.\n_The office is on the left._\n\n**Right** — Direction to the east side.\n_Turn right at the corner._\n\n**Straight** — Not turning.\n_Go straight for ten meters._\n\n**Near** — A short distance.\n_It is near the school._\n\n**Far** — A long distance.\n_It is not very far._\n\n**Street** — A road in a city.\n_Which street is this?_\n\n**Building** — A structure.\n_The big building is here._\n\n**Map** — A drawing of a place.\n_Look at the map._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
