INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('65a7951e-16ed-5f1c-a772-81836bfa29d5', 'ed0e150d-1d96-5b5f-b079-671a038f518e', 'text', 'Vocabulary', '{"text": "## Asking About Prices\n\n**Cost** — The price.\n_How much does it cost?_\n\n**Price** — The value of an item.\n_What is the price?_\n\n**Cheap** — Low price.\n_This book is very cheap._\n\n**Expensive** — High price.\n_That is too expensive._\n\n**Money** — The currency.\n_I do not have much money._\n\n**Pay** — Giving money.\n_Can I pay by card?_\n\n**Dollar** — A unit of currency.\n_It costs ten dollars._\n\n**Total** — The final sum.\n_What is the total price?_\n\n**Buy** — Getting for money.\n_I want to buy this._\n\n**Free** — Zero cost.\n_Is this help free?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
