INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('10fd75e0-3cd1-572e-a917-5d4a39f72261', '9dc4f7ec-2947-57b8-86ae-24c4d3033f86', 'text', 'Vocabulary', '{"text": "## Expressing Ability & Possibility\n\n**Can** — Able to do.\n_I can speak English._\n\n**Could** — Past ability or polite request.\n_I could do it then._\n\n**May** — Permission or possibility.\n_May I go now?_\n\n**Might** — Small possibility.\n_It might rain today._\n\n**Will** — Future certainty.\n_I will study tomorrow._\n\n**Would** — Hypothetical situation.\n_I would like some tea._\n\n**Able** — Having the skill.\n_I am able to help._\n\n**Possible** — Can happen.\n_Is that possible?_\n\n**Impossible** — Cannot happen.\n_That is not impossible._\n\n**Skill** — An ability.\n_This is a great skill._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
