INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e2d0f950-21a9-5d3d-8c93-079097102365', '8425a01e-7a3c-54b4-9e4e-45ce06b964db', 'text', 'Vocabulary', '{"text": "## Making Suggestions\n\n**Let''s** — Suggesting we do.\n_Let''s study together now._\n\n**Should** — Good idea.\n_You should read this._\n\n**Maybe** — Possibility.\n_Maybe we go there._\n\n**How** — Asking about a method.\n_How about lunch now?_\n\n**Suggest** — Proposing an idea.\n_I suggest we talk._\n\n**Idea** — A thought.\n_That is a good idea._\n\n**Plan** — A proposal.\n_What is your plan?_\n\n**Ready** — Prepared to act.\n_Are you ready to go?_\n\n**Agree** — Saying yes.\n_I agree with you._\n\n**Try** — Attempting an action.\n_Let''s try this book._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
