VALUES ('a4423ddf-61ab-5e25-a98b-31480f77fbfa', 'c7ab1eb9-3fc9-500a-a486-7a2de2197ddc', 'text', 'Vocabulary', '{"text": "## Social Etiquette (Speaking)\n\n**Hello** — Greeting.\n_Hello, how are you?_\n\n**Goodbye** — Departing.\n_Goodbye, see you later._\n\n**Thanks** — Gratitude.\n_Thanks for your help._\n\n**Welcome** — Polite reply.\n_You are very welcome._\n\n**Excuse** — Interrupting politely.\n_Excuse me, teacher._\n\n**Sorry** — Apology.\n_I am sorry for that._\n\n**Please** — Being polite.\n_Please listen to me._\n\n**Pardon** — Asking repeat.\n_Pardon me, please?_\n\n**Nice** — Being kind.\n_Nice to meet you._\n\n**Help** — Being supportive.\n_I can help you._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
