INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('6c9ccb0e-fae5-5459-9ac9-8a66cd6cc614', '9a4d56a2-e34e-5501-b347-af22c980b869', 'text', 'Vocabulary', '{"text": "## Asking About Needs\n\n**Need** — Require.\n_I need a pen now._\n\n**Want** — Desire.\n_Do you want this?_\n\n**Help** — Assistance.\n_Do you need any help?_\n\n**Have** — Possess.\n_Do you have time?_\n\n**Take** — Accept.\n_Take this book, please._\n\n**Use** — Utilize.\n_Can I use this?_\n\n**Give** — Offer.\n_Give me your answer._\n\n**Find** — Locate.\n_I cannot find it._\n\n**Need** — Essential.\n_Is this needed?_\n\n**Please** — Polite requirement.\n_Please, I need it._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
