INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('23fdd33a-24e0-51e1-bdfc-1417a32f4ed9', 'f7483767-6047-5dd1-b63d-a2cfa7dbe09f', 'text', 'Vocabulary', '{"text": "## Planning Future Actions\n\n**Will** — Future action.\n_I will study tomorrow._\n\n**Going** — Planned future.\n_I am going to work._\n\n**Future** — Time coming.\n_Think of the future._\n\n**Next** — Following.\n_Next week I work._\n\n**Plan** — Prepared intent.\n_My plan is simple._\n\n**Soon** — Very near.\n_I will see you soon._\n\n**Tomorrow** — Following day.\n_See you tomorrow morning._\n\n**Ready** — Prepared.\n_Are you ready now?_\n\n**Want** — Future desire.\n_I want to graduate._\n\n**Succeed** — Future goal.\n_I will succeed soon._\n"}', 0, NOW(), NOW())
