INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('ff452afa-90cc-5a34-900e-d92c28d59ff6', '29c80390-a8ab-5eae-b1fe-e8532a6da37a', 'text', 'Vocabulary', '{"text": "## Meeting People & Introductions\n\n**Meet** — To see and talk to someone for the first time.\n_Nice to meet you._\n\n**Name** — The word people call you.\n_Her name is Husna._\n\n**Friend** — A person you like and know well.\n_This is my friend from class._\n\n**Introduce** — To tell someone who another person is.\n_Let me introduce my classmate._\n\n**Welcome** — Greet someone warmly to a place.\n_Welcome to our English club!_\n\n**This** — Used to point out a person or thing close by.\n_This is the teacher''s desk._\n\n**New** — Recently arrived or made.\n_We have a new student today._\n\n**Guy / Person** — An individual human being.\n_He is a very kind person._\n\n**Pleased** — Feeling happy or satisfied.\n_I am pleased to be your teacher._\n\n**Everyone** — All the people in a group.\n_Hello everyone, let us begin._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
