INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4dabb074-4491-5262-a041-b958fe5b2a21', '52f83508-e8b2-5048-81d7-b389f1ad39ce', 'text', 'Vocabulary', '{"text": "## Sharing Personal Information\n\n**Live** — To have your home in a specific place.\n_I live in a peaceful city._\n\n**City** — A large town.\n_This city is very beautiful._\n\n**Age** — The number of years you have lived.\n_Can you tell me your age?_\n\n**Years** — Measurement of time for age.\n_I am twenty-five years old._\n\n**Job** — The work you do for money.\n_What is your father''s job?_\n\n**Family** — Parents and siblings together.\n_I love my family very much._\n\n**Single** — Not married.\n_Are you single or married?_\n\n**Married** — Having a husband or wife.\n_My brother is happily married._\n\n**Phone** — Device used to call or text.\n_What is your phone number?_\n\n**Address** — The specific number and street where you live.\n_Please write down your address._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
