INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d774d564-d506-5b09-baae-b8316f32bc0f', 'cfd86360-4dab-5a97-b315-ec9ce7103c6b', 'text', 'Vocabulary', '{"text": "## Expressing Simple Opinions\n\n**Think** — To have an opinion or belief.\n_I think English is beautiful._\n\n**Beautiful** — Very nice to look at or hear.\n_The carpet pattern is beautiful._\n\n**Interesting** — Keeping your attention or curiosity.\n_This book topic is interesting._\n\n**Boring** — Not interesting at all.\n_The movie was a bit boring._\n\n**Easy** — Simple to do or learn.\n_Grammar is easy with practice._\n\n**Difficult** — Hard to do or understand.\n_This task is not difficult._\n\n**Good** — Positive or high quality.\n_Your speaking is very good._\n\n**Bad** — Not good; negative.\n_Smoking is a bad habit._\n\n**Best** — Better than all others.\n_This is the best learning app._\n\n**Great** — Very big, important, or excellent.\n_That is a great idea._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
