INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('91850dc3-104e-598c-ae2b-ebfd235eb6e4', 'e839c118-29d0-5a98-a6cc-3e1bf67645b6', 'text', 'Vocabulary', '{"text": "## Making Small Talk (The Weather)\n\n**Weather** — The state of the air outside (hot, cold, wet).\n_The weather is nice today._\n\n**Hot** — Having a high temperature.\n_It is very hot in July._\n\n**Cold** — Having a low temperature.\n_The winter here is cold._\n\n**Warm** — Pleasantly hot; not too hot.\n_The room is nice and warm._\n\n**Sunny** — Bright with light from the sun.\n_I love a sunny morning._\n\n**Rainy** — Having a lot of rain drops falling.\n_Bring an umbrella on rainy days._\n\n**Cloudy** — The sky is full of dark clouds.\n_It is cloudy this afternoon._\n\n**Windy** — With a lot of fast moving air.\n_It is too windy to play outside._\n\n**Nice** — Pleasant or enjoyable.\n_Have a nice evening._\n\n**Sky** — The space above the earth.\n_Look at the clear blue sky._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
