INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('6c3ad9c9-45d9-5ae2-af0d-c36a550a2b72', 'e89e6b8e-c8bf-5e60-ba91-06d8f6e9f229', 'text', 'Vocabulary', '{"text": "## Spoken Fillers & Reactions\n\n**Really** — Expressing surprise or emphasis.\n_Really? That is wonderful!_\n\n**Wow** — Showing strong admiration or surprise.\n_Wow, your English is perfect._\n\n**Oh** — Used to express understanding or realization.\n_Oh, I understand now._\n\n**Well** — Used to pause or start speaking.\n_Well, let me try again._\n\n**Right** — Expressing agreement while listening.\n_Right, that makes sense._\n\n**I see** — Showing that you understand the situation.\n_I see, you need more time._\n\n**Cool** — Slang for excellent or trendy.\n_That is a cool phone._\n\n**Okay** — Showing agreement or acceptance.\n_Okay, let us study together._\n\n**True** — Agreeing that a point is correct.\n_That is very true._\n\n**Sure** — Saying yes confidently.\n_Sure, I can help you._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
