INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('98d79a50-f47a-5b6c-9ed8-5e4a352494de', '4a3e9c20-e8e9-5f06-b3ec-cb343a796ade', 'text', 'Vocabulary', '{"text": "## Inviting & Accepting\n\n**Invite** — To ask someone to an event or home.\n_I want to invite you._\n\n**Come** — Move toward a place with the speaker.\n_Come to my house tonight._\n\n**House / Home** — The building where someone lives.\n_My home is near the school._\n\n**Tea** — A common hot drink offered to guests.\n_Would you like some tea?_\n\n**Dinner** — The main meal of the day, eaten in the evening.\n_Let us have dinner together._\n\n**Love** — Enthusiastic acceptance.\n_I would love to come._\n\n**Sound** — How an idea seems.\n_That sounds like fun._\n\n**Thank** — Expressing appreciation for the offer.\n_Thank you for the invitation._\n\n**Free** — Having open time; not busy.\n_Are you free this weekend?_\n\n**Join** — To do an activity with someone.\n_Join us for a cup of coffee._\n\n**Lesson** — Structured learning hour.\n_Do your homework after the lesson._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
