INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f34cdda4-e8bb-56b1-aa00-af36cd5e4f12', '7be0e0f5-6a87-5a1d-8c27-960d2fd5e439', 'text', 'Vocabulary', '{"text": "## Polite Declining & Excuses\n\n**But** — Used to connect a contrasting idea.\n_I want to come, but I cannot._\n\n**Sorry** — Expression of regret.\n_I am sorry, I am too busy._\n\n**Busy** — Having a lot of work or tasks to do.\n_The teacher is busy right now._\n\n**Working** — Performing professional duties.\n_I am working until late tonight._\n\n**Next** — The one immediately following.\n_Maybe next time, my friend._\n\n**Must** — Highly necessary action.\n_I must study for the test._\n\n**Tired** — Needing sleep or relaxation.\n_I am too tired to go out._\n\n**Rain** — Water falling from clouds keeping you inside.\n_I cannot walk because of the rain._\n\n**Plans** — Arrangements already made.\n_I have other plans today._\n\n**Later** — At a point in the future.\n_Can we talk about it later?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
