INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('48f25783-7a4e-5cba-96b7-902f520e072a', '0d151445-690a-5d64-95c9-2ca1cadffe52', 'text', 'Vocabulary', '{"text": "## Checking for Understanding\n\n**Understand** — To know the meaning of what is said.\n_Do you understand me?_\n\n**Mean** — To intend to say or define.\n_What do you mean by that?_\n\n**Know** — Having information or certainty.\n_I don''t know this grammar rule._\n\n**Clear** — Easy to follow and comprehend.\n_Is my explanation clear to you?_\n\n**Listen** — Paying close attention with your ears.\n_Please listen to my pronunciation._\n\n**Follow** — Keeping up with the speaker''s ideas.\n_Are you following the story?_\n\n**Question** — A sentence that asks for an answer.\n_Ask a question if you are confused._\n\n**Repeat** — Saying the words one more time.\n_Could you repeat that word?_\n\n**Say** — To pronounce language aloud.\n_How do you say this in English?_\n\n**Word** — A single spoken or written unit of language.\n_What does this word mean?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
