INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f7219d6b-85a7-55c9-ae59-6d312395e00b', '66ddbf92-8073-5a8b-b2d5-44ca92f4bfd6', 'text', 'Vocabulary', '{"text": "## Saying Goodbye Politely\n\n**Goodbye** — Saying farewell to someone leaving.\n_Goodbye, see you at school._\n\n**See you** — Conversational way to say goodbye.\n_See you again tomorrow morning._\n\n**Day** — The daylight hours.\n_Have a wonderful day ahead._\n\n**Night** — The hours of darkness before sleep.\n_Good night, sleep well._\n\n**Take care** — Wishing safety and health to someone.\n_Take care on your way home._\n\n**Meeting** — The act of coming together.\n_It was a great meeting today._\n\n**Talk** — Verbal communication.\n_We will talk again very soon._\n\n**Friend** — Term of affection for a peer.\n_Goodbye, my dear friend._\n\n**Safe** — Free from danger or harm.\n_Have a safe trip tomorrow._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
