INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e7ce4ffe-19d1-522e-9868-eb7af0b09b21', 'a030cf71-15b0-5a35-995b-ef55617745b7', 'text', 'Vocabulary', '{"text": "## Time and Schedules\n\n**Schedule** — A plan for when things will happen.\n_My schedule is very full._\n\n**Appointment** — An arranged meeting time.\n_I have an appointment at noon._\n\n**Meeting** — A group coming together for work.\n_The meeting is in ten minutes._\n\n**Early** — Before the expected time.\n_I always arrive early._\n\n**On time** — Exactly at the planned time.\n_Please be on time._\n\n**Late** — After the expected time.\n_Sorry, I am a bit late._\n\n**Hour** — Sixty minutes of time.\n_I study for one hour._\n\n**Minute** — Sixty seconds of time.\n_Wait one minute, please._\n\n**Clock** — The device that tells the time.\n_The clock is on the wall._\n\n**Morning** — The first part of the day.\n_I study in the morning._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
