INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('183cc988-449d-575c-bc1e-a0155e022c00', '99955f45-ab0e-58ee-bbf9-6f19157a55ec', 'text', 'Vocabulary', '{"text": "## Work and Professional Life\n\n**Career** — The work a person does for a long time.\n_I love my teaching career._\n\n**Office** — A room where people work.\n_He is in the office now._\n\n**Task** — A piece of work to be done.\n_I have a difficult task._\n\n**Professional** — Relating to work or job skill.\n_Act in a professional way._\n\n**Employer** — The person or company you work for.\n_My employer is very kind._\n\n**Salary** — Money paid for work.\n_My salary is good._\n\n**Business** — The activity of making money.\n_I am starting a business._\n\n**Email** — A digital letter.\n_Did you send the email?_\n\n**Project** — A special, planned piece of work.\n_This project is very big._\n\n**Team** — A group working together.\n_I work with a great team._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
