INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b310242e-3318-52d1-a27b-149c74fa395f', '978d91ae-32ff-5224-85cd-72e92b46668a', 'text', 'Vocabulary', '{"text": "## Daily Habits & Routines\n\n**Wake up** — To stop sleeping.\n_I wake up at six._\n\n**Breakfast** — The first meal of the day.\n_I eat breakfast quickly._\n\n**Commute** — The trip to work or school.\n_My commute is very long._\n\n**Break** — A short time to rest.\n_We have a ten-minute break._\n\n**Lunch** — The meal in the middle of the day.\n_Let us have lunch together._\n\n**Finish** — To bring to an end.\n_I finish work at five._\n\n**Relax** — To rest and feel calm.\n_I like to relax at home._\n\n**Dinner** — The meal in the evening.\n_Dinner is ready now._\n\n**Habit** — Something you do regularly.\n_Reading is a good habit._\n\n**Routine** — The regular way you do things.\n_My routine is very simple._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
