INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('abe337e5-676b-5880-a0a3-b68e158c4bdc', '4973c2d1-e2d3-50cf-ae28-dc62df2cec72', 'text', 'Vocabulary', '{"text": "## Learning and Schooling\n\n**Lesson** — A period of learning.\n_The English lesson is here._\n\n**Student** — A person learning in a school.\n_You are an excellent student._\n\n**Teacher** — A person who instructs others.\n_The teacher is very helpful._\n\n**Study** — To read and learn something.\n_I need to study today._\n\n**Classroom** — A room for learning.\n_Our classroom is clean._\n\n**Homework** — Work done at home.\n_Did you do your homework?_\n\n**Exam** — A test of your knowledge.\n_The exam is very difficult._\n\n**Grade** — A mark for school work.\n_I got a good grade._\n\n**Understand** — To get the meaning.\n_I understand this lesson._\n\n**Learn** — To get new knowledge.\n_I want to learn English._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
