INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('fea6d6a6-a550-58e7-8f36-e220a02a31b5', '2f418cce-b350-501f-acdb-15f31a30f06f', 'text', 'Vocabulary', '{"text": "## Planning Future Goals\n\n**Goal** — Something you want to achieve.\n_What is your main goal?_\n\n**Success** — Achieving your goals.\n_Hard work leads to success._\n\n**Future** — Time after now.\n_I think about the future._\n\n**Plan** — A method to achieve a goal.\n_I have a good plan._\n\n**Prepare** — To get ready.\n_I prepare for my class._\n\n**Decide** — To choose something.\n_I decide to study hard._\n\n**Improve** — To make better.\n_I want to improve fast._\n\n**Master** — To become an expert.\n_I want to master English._\n\n**Advance** — To move forward.\n_I want to advance today._\n\n**Believe** — To hold as true.\n_I believe I can do it._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
