VALUES ('f90215a6-2368-50cb-9ce8-68f4d289a59e', 'a3eeecb3-ce2c-53e5-9fc2-cd015da1b44c', 'text', 'Vocabulary', '{"text": "## Asking for Assistance\n\n**Help** — To give assistance.\n_Please, can you help me?_\n\n**Assist** — To support someone.\n_I can assist you now._\n\n**Support** — Encouragement or help.\n_I need your support today._\n\n**Explain** — To make something clear.\n_Can you explain this word?_\n\n**Clarify** — To make simpler.\n_Please clarify that point._\n\n**Repeat** — To say again.\n_Please repeat that sentence._\n\n**Guide** — To lead the way.\n_Can you guide me?_\n\n**Favor** — A kind, helpful action.\n_Can I ask a favor?_\n\n**Handle** — To manage a situation.\n_I can handle this task._\n\n**Solve** — To find the answer.\n_We can solve this together._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
