VALUES ('d3b0c997-264f-5837-9c8c-29e1cd1451bb', '179eebe8-831a-5f76-aeff-778bc1aaad64', 'text', 'Vocabulary', '{"text": "## Describing Quality\n\n**High** — Above average.\n_That is high quality._\n\n**Low** — Below average.\n_That is a low price._\n\n**Excellent** — Extremely good.\n_Your work is excellent._\n\n**Perfect** — Without any mistakes.\n_This is a perfect answer._\n\n**Correct** — Free from errors.\n_Is this sentence correct?_\n\n**Wrong** — Not true or correct.\n_That answer is wrong._\n\n**Simple** — Easy to understand.\n_Keep your English simple._\n\n**Complex** — Having many parts.\n_The task is very complex._\n\n**Useful** — Helpful in some way.\n_This tool is very useful._\n\n**Best** — Of the highest quality.\n_This is the best book._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
