INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('a5c7f029-f31b-516f-88c3-84d82f4ffd9d', '6625994a-4f49-53f6-b0db-fb75282beba3', 'text', 'Vocabulary', '{"text": "## Dealing with Problems\n\n**Problem** — Something that needs a fix.\n_Do you have a problem?_\n\n**Fix** — To make work again.\n_I can fix it soon._\n\n**Hard** — Difficult to do.\n_It is very hard work._\n\n**Confused** — Not understanding.\n_I am a bit confused._\n\n**Error** — A mistake.\n_Find the error here._\n\n**Lost** — Cannot find way.\n_I am a bit lost._\n\n**Worry** — To feel concerned.\n_Do not worry, please._\n\n**Solution** — Answer to problem.\n_What is the solution?_\n\n**Help** — Assistance for issues.\n_I need your help now._\n\n**Patience** — Waiting calmly.\n_Please have some patience._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
