INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('8c295be5-07dd-5e1a-8f94-605408e63960', '388ac049-7bc7-5081-90c3-d1dd65e08bf7', 'text', 'Vocabulary', '{"text": "## Milestone Reflection\n\n**Milestone** — An important event.\n_This is a big milestone._\n\n**Progress** — Moving forward well.\n_You made great progress._\n\n**Skill** — Ability to do well.\n_You have a new skill._\n\n**Fluent** — Speaking smoothly.\n_I want to be fluent._\n\n**Practice** — Repetition for skill.\n_Practice makes you perfect._\n\n**Confident** — Feeling sure of self.\n_Be confident, my friend._\n\n**Achievement** — Something reached.\n_That is an achievement._\n\n**Ready** — Prepared for more.\n_Are you ready now?_\n\n**Continue** — Go on with work.\n_Continue to study hard._\n\n**Growth** — Improvement/increase.\n_Your growth is great._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
